#!/usr/bin/env python3
import json
import os
import re
import zipfile
from pathlib import Path

from lxml import etree


WORK_DIR = Path('/tmp/hwpx_work')
TEMPLATE_DIR = WORK_DIR / 'template_contents'
JSON_PATH = Path('/root/training_feedback.json')
OUT_PATH = Path('/root/training_feedback_ready.hwpx')


def load_json_values(path: Path) -> dict:
    with path.open('r', encoding='utf-8') as f:
        return json.load(f)


def digits_only(value) -> str:
    if value is None:
        return ''
    if isinstance(value, (int, float)):
        s = str(value)
    else:
        s = str(value)
    return ''.join(ch for ch in s if ch.isdigit())


def parse_satisfaction_score(value) -> str:
    # Accept forms like "4.5/5.0", "4.5", 4.5, "4"
    if value is None:
        return ''
    if isinstance(value, (int, float)):
        score = float(value)
        return f"{score:.1f}점 (5.0점 만점)"

    s = str(value).strip()
    m = re.search(r"(\d+(?:\.\d+)?)", s)
    if not m:
        return ''
    score = float(m.group(1))
    return f"{score:.1f}점 (5.0점 만점)"


def append_followup(opinion: str) -> str:
    if opinion is None:
        opinion = ''
    s = str(opinion)
    suffix = '후속 심화반 검토 요망.'
    if s.endswith(suffix):
        return s
    if s.endswith(' ') or s == '':
        return s + suffix
    return s + ' ' + suffix


def prepare_values(raw: dict) -> dict:
    prepared = dict(raw)

    # Derived values
    if '참석자수' in raw:
        prepared['참석자수'] = digits_only(raw.get('참석자수'))
    if '만족도' in raw:
        prepared['만족도'] = parse_satisfaction_score(raw.get('만족도'))

    # 종합의견 (or fallback key if template uses a different one)
    if '종합의견' in raw:
        prepared['종합의견'] = append_followup(raw.get('종합의견'))

    return prepared


def get_hp_namespace(root: etree._Element) -> str:
    # Find the namespace URI that the 'hp' prefix maps to; otherwise use root's ns.
    nsmap = root.nsmap or {}
    if 'hp' in nsmap and nsmap['hp']:
        return nsmap['hp']
    if None in nsmap and nsmap[None]:
        return nsmap[None]
    if root.tag.startswith('{'):
        return root.tag.split('}', 1)[0][1:]
    raise RuntimeError('Could not determine XML namespace for hp')


def paragraph_text(p: etree._Element, hp_ns: str) -> str:
    texts = p.xpath('.//hp:t', namespaces={'hp': hp_ns})
    return ''.join(t.text or '' for t in texts)


def substitute_placeholders(text: str, values: dict) -> str:
    # Replace every {{key}} exactly; if key not found, leave it unchanged.
    def repl(m):
        key = m.group(1)
        if key in values:
            return str(values[key])
        return m.group(0)

    return re.sub(r"\{\{([^{}]+)\}\}", repl, text)


def remove_lineseg_arrays(p: etree._Element, hp_ns: str) -> None:
    for tag in ['linesegArray', 'linesegarray', 'lineSegArray', 'linesegArray']:
        nodes = p.xpath(f'./hp:{tag}', namespaces={'hp': hp_ns})
        for n in nodes:
            p.remove(n)


def first_run_rpr(p: etree._Element, hp_ns: str):
    runs = p.xpath('./hp:run', namespaces={'hp': hp_ns})
    if not runs:
        return None
    rpr = runs[0].xpath('./hp:rPr', namespaces={'hp': hp_ns})
    if not rpr:
        return None
    return rpr[0]


def clear_runs(p: etree._Element, hp_ns: str) -> None:
    runs = p.xpath('./hp:run', namespaces={'hp': hp_ns})
    for r in runs:
        p.remove(r)


def build_single_run(p: etree._Element, hp_ns: str, substituted: str, template_rpr: etree._Element | None) -> None:
    run = etree.Element(f'{{{hp_ns}}}run')
    if template_rpr is not None:
        run.append(etree.fromstring(etree.tostring(template_rpr)))
    t = etree.SubElement(run, f'{{{hp_ns}}}t')
    t.text = substituted
    p.insert(0, run)


def process_section_xml(path: Path, values: dict) -> bool:
    """Return True if file modified."""
    raw_bytes = path.read_bytes()
    parser = etree.XMLParser(remove_blank_text=False, recover=False)
    root = etree.fromstring(raw_bytes, parser=parser)
    hp_ns = get_hp_namespace(root)

    modified = False
    ps = root.xpath('.//hp:p', namespaces={'hp': hp_ns})
    for p in ps:
        full_text = paragraph_text(p, hp_ns)
        if '{{' not in full_text:
            continue
        substituted = substitute_placeholders(full_text, values)
        if substituted == full_text:
            # contains {{ but no matching keys; leave untouched per requirement
            continue

        template_rpr = first_run_rpr(p, hp_ns)

        clear_runs(p, hp_ns)
        remove_lineseg_arrays(p, hp_ns)
        build_single_run(p, hp_ns, substituted, template_rpr)
        modified = True

    if not modified:
        return False

    # Preserve XML declaration and standalone if present
    # lxml's fromstring doesn't expose standalone easily; detect from raw header
    xml_header = raw_bytes.split(b'?>', 1)[0] if raw_bytes.startswith(b'<?xml') else b''
    standalone = None
    if xml_header:
        m = re.search(br"standalone=['\"](yes|no)['\"]", xml_header)
        if m:
            standalone = m.group(1).decode('ascii')

    out_bytes = etree.tostring(
        root,
        xml_declaration=True,
        encoding='UTF-8',
        standalone=standalone,
    )
    path.write_bytes(out_bytes)
    return True


def collect_section_xmls(base_dir: Path) -> list[Path]:
    xmls = []
    for p in base_dir.rglob('section*.xml'):
        if p.is_file():
            xmls.append(p)
    return sorted(xmls)


def hwpx_zip(src_dir: Path, out_path: Path) -> None:
    # Write mimetype first and uncompressed if present
    mimetype = src_dir / 'mimetype'
    with zipfile.ZipFile(out_path, 'w') as z:
        if mimetype.exists():
            z.write(mimetype, 'mimetype', compress_type=zipfile.ZIP_STORED)

        for root, dirs, files in os.walk(src_dir):
            for f in files:
                full = Path(root) / f
                rel = full.relative_to(src_dir).as_posix()
                if rel == 'mimetype':
                    continue
                z.write(full, rel, compress_type=zipfile.ZIP_DEFLATED)


def validate_result(out_path: Path, prepared: dict) -> None:
    val_dir = WORK_DIR / 'validate_contents'
    if val_dir.exists():
        for p in val_dir.rglob('*'):
            if p.is_file():
                p.unlink()
        for p in sorted(val_dir.glob('*'), reverse=True):
            if p.is_dir():
                pass
    if val_dir.exists():
        # clean tree
        import shutil
        shutil.rmtree(val_dir)
    val_dir.mkdir(parents=True, exist_ok=True)

    with zipfile.ZipFile(out_path, 'r') as z:
        z.extractall(val_dir)

    # 1) No placeholders remain
    any_placeholders = []
    for p in val_dir.rglob('*'):
        if p.is_file() and p.suffix.lower() in {'.xml', '.rels', '.txt', ''}:
            try:
                data = p.read_text(encoding='utf-8', errors='ignore')
            except Exception:
                continue
            if '{{' in data:
                any_placeholders.append(str(p))
    if any_placeholders:
        raise AssertionError('Placeholders remain in: ' + ', '.join(any_placeholders))

    # 2) Print text content of all section XMLs and check rules
    section_paths = collect_section_xmls(val_dir / 'Contents') if (val_dir / 'Contents').exists() else []
    for sp in section_paths:
        b = sp.read_bytes()
        root = etree.fromstring(b)
        hp_ns = get_hp_namespace(root)
        texts = root.xpath('.//hp:t', namespaces={'hp': hp_ns})
        content = ''.join(t.text or '' for t in texts)
        print(f'--- {sp.relative_to(val_dir).as_posix()} ---')
        print(content)

        # Verify no lineseg arrays remain in modified paragraphs (we removed only in modified paras)
        # We check generally: any lineseg array indicates either untouched paragraph or bug.
        # But requirement specifically: none remain in modified paragraphs.
        # We'll assert none remain at all in paragraphs that contain substituted values.
        ps = root.xpath('.//hp:p', namespaces={'hp': hp_ns})
        for p in ps:
            ptext = paragraph_text(p, hp_ns)
            if any(str(prepared.get(k, '')) in ptext and str(prepared.get(k, '')) != '' for k in prepared.keys()):
                bad = p.xpath('./hp:linesegArray | ./hp:lineSegArray | ./hp:linesegarray', namespaces={'hp': hp_ns})
                if bad:
                    raise AssertionError(f'linesegArray still present in modified paragraph in {sp}')

    # 3) 참석자수 digits only
    참석 = prepared.get('참석자수', '')
    if not re.fullmatch(r'\d*', str(참석)):
        raise AssertionError(f"참석자수 not digits only: {참석}")

    # 4) 만족도 pattern
    만족 = prepared.get('만족도', '')
    if not re.fullmatch(r'\d+(?:\.\d)?점 \(5\.0점 만점\)', str(만족)):
        raise AssertionError(f"만족도 pattern mismatch: {만족}")

    # 5) 종합의견 suffix
    종합 = prepared.get('종합의견', '')
    if not str(종합).endswith('후속 심화반 검토 요망.'):
        raise AssertionError('종합의견 does not end with suffix')


def main():
    raw = load_json_values(JSON_PATH)
    prepared = prepare_values(raw)

    section_files = collect_section_xmls(TEMPLATE_DIR / 'Contents')
    if not section_files:
        raise RuntimeError('No section XML files found')

    touched = []
    for p in section_files:
        # Only process files that contain '{{'
        if b'{{' not in p.read_bytes():
            continue
        if process_section_xml(p, prepared):
            touched.append(p)

    hwpx_zip(TEMPLATE_DIR, OUT_PATH)
    validate_result(OUT_PATH, prepared)

    print('OK: wrote', OUT_PATH)
    if touched:
        print('Modified:')
        for t in touched:
            print(' -', t)


if __name__ == '__main__':
    main()

